<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT * FROM clients WHERE id=?');$s->execute([$id]);$client=$s->fetch();if(!$client){http_response_code(404);exit('Client not found.');}$link=null;if($_SERVER['REQUEST_METHOD']==='POST'){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$days=max(1,min(90,(int)($_POST['days']??30)));$q=$db->prepare('INSERT INTO client_portal_sessions(client_id,token_hash,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL ? DAY))');$q->execute([$id,$hash,$days]);$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$base=rtrim(dirname(dirname($_SERVER['SCRIPT_NAME'])),'/');$link=$scheme.'://'.$_SERVER['HTTP_HOST'].$base.'/portal/?token='.urlencode($token);}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Portal Access</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card mx-auto" style="max-width:760px"><div class="card-body"><h1 class="h4">Client Portal Access</h1><p><?=$e($client['name'])?><?=$client['company']?' · '.$e($client['company']):''?></p><form method="post" class="row g-2 mb-4"><div class="col-md-8"><select class="form-select" name="days"><option value="7">7 days</option><option value="30" selected>30 days</option><option value="60">60 days</option><option value="90">90 days</option></select></div><div class="col-md-4"><button class="btn btn-dark w-100">Generate Secure Link</button></div></form><?php if($link):?><div class="alert alert-success"><strong>Portal link generated.</strong><div class="input-group mt-2"><input class="form-control" value="<?=$e($link)?>" readonly><button class="btn btn-outline-secondary" type="button" onclick="navigator.clipboard.writeText(this.previousElementSibling.value)">Copy</button></div><small class="d-block mt-2">Store/share this link securely. The raw token is not stored in the database.</small></div><?php endif;?></div></div></main></body></html>